from pathlib import Path
import difflib
b = '''\"\"\"Deliver stored payloads as downloads.\"\"\"


def run(media_sink, claimed_type, filename, payload_bytes):
    if not isinstance(claimed_type, str) or not isinstance(filename, str):
        return \"invalid\"
    if not isinstance(payload_bytes, bytes):
        return \"invalid\"
    media_sink.deliver(\"download\", \"application/octet-stream\", filename, payload_bytes)
    return \"download\"
'''
u = '''\"\"\"Deliver stored payloads using their recorded passive classification.\"\"\"

from fixture_api.contracts import X10_PASSIVE_TYPES


def run(media_sink, claimed_type, filename, payload_bytes):
    if not isinstance(claimed_type, str) or not isinstance(filename, str):
        return \"invalid\"
    if not isinstance(payload_bytes, bytes):
        return \"invalid\"
    if claimed_type in X10_PASSIVE_TYPES:
        media_sink.deliver(\"inline\", claimed_type, filename, payload_bytes)
        return \"inline\"
    media_sink.deliver(\"download\", \"application/octet-stream\", filename, payload_bytes)
    return \"download\"
'''
r = '''\"\"\"Validate passive content before selecting inline delivery.\"\"\"

from fixture_api.contracts import X10_PASSIVE_TYPES


def _classify(payload):
    matches = []
    if payload.startswith(b\"TXT\\\\x00\") and len(payload) > 4:
        if all(32 <= byte <= 126 or byte in (9, 10, 13) for byte in payload[4:]):
            matches.append(\"text/plain\")
    if payload.startswith(b\"PIX\\\\x00\") and len(payload) >= 6:
        width, height = payload[4], payload[5]
        if width and height and len(payload) == 6 + width * height * 3:
            matches.append(\"image/x-local-pixels\")
    return matches[0] if len(matches) == 1 else None


def run(media_sink, claimed_type, filename, payload_bytes):
    if not isinstance(claimed_type, str) or not isinstance(filename, str):
        return \"invalid\"
    if not isinstance(payload_bytes, bytes):
        return \"invalid\"
    verified_type = _classify(payload_bytes)
    if verified_type in X10_PASSIVE_TYPES and claimed_type == verified_type:
        media_sink.deliver(\"inline\", verified_type, filename, payload_bytes)
        return \"inline\"
    media_sink.deliver(\"download\", \"application/octet-stream\", filename, payload_bytes)
    return \"download\"
'''
for path, content in [('candidate/B/app/service.py', b), ('.scratch/U/app/service.py', u), ('.scratch/R/app/service.py', r)]:
    Path(path).write_text(content, encoding='utf-8')
    Path(path).chmod(0o644)
for name, old, new in [('feature', b, u), ('security', u, r)]:
    patch = 'diff --git a/app/service.py b/app/service.py\\n' + ''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True), fromfile='a/app/service.py', tofile='b/app/service.py'))
    path = Path('candidate') / (name + '.patch')
    path.write_text(patch, encoding='utf-8')
    path.chmod(0o644)
PY"

